/// `local:00000000000000000000000000000000/main.Surface`.
pub trait Surface {
    fn eval(&mut self, arg0: SurfaceEvalArg0) -> hd_run_wasmtime::native::HostResult<i32>;
    fn twice(&mut self, arg0: SurfaceTwiceArg0) -> hd_run_wasmtime::native::HostResult<SurfaceTwiceResult>;
}

/// Calls the method at index `method` of the registered `Surface` with its
/// encoded arguments and returns its encoded result, or a suspending
/// method's pending call.
#[allow(non_snake_case)]
pub fn dispatch_Surface(provider: &mut dyn std::any::Any, method: usize, args: &[u8], handles: &mut hd_run_wasmtime::native::Handles) -> hd_run_wasmtime::native::Dispatched {
    let provider = hd_run_wasmtime::native::wire::provider::<Box<dyn Surface>>(provider)?;
    match method {
        0 => {
            let d = &mut hd_run_wasmtime::native::wire::Decoder::new(args);
            let arg0 = SurfaceEvalArg0::wire_decode(d)?;
            d.finish()?;
            let value = provider.eval(arg0).map_err(hd_run_wasmtime::native::Failure::Threw)?;
            let mut enc = hd_run_wasmtime::native::wire::Encoder::new(handles);
            let e = &mut enc;
            e.signed(i64::from(value));
            Ok(hd_run_wasmtime::native::Answer::Ready(enc.into_bytes()))
        }
        1 => {
            let d = &mut hd_run_wasmtime::native::wire::Decoder::new(args);
            let arg0 = SurfaceTwiceArg0::wire_decode(d)?;
            d.finish()?;
            let value = provider.twice(arg0).map_err(hd_run_wasmtime::native::Failure::Threw)?;
            let mut enc = hd_run_wasmtime::native::wire::Encoder::new(handles);
            let e = &mut enc;
            SurfaceTwiceResult::wire_encode(value, e)?;
            Ok(hd_run_wasmtime::native::Answer::Ready(enc.into_bytes()))
        }
        _ => Err(hd_run_wasmtime::native::wire::unknown_method(method).into()),
    }
}

/// The providers of this module's root host traits.
pub struct Bindings;

impl Bindings {
    #[must_use]
    pub fn builder() -> BindingsBuilder {
        BindingsBuilder {
            surface: None,
        }
    }
}

pub struct BindingsBuilder {
    surface: Option<Box<dyn Surface>>,
}

impl BindingsBuilder {
    #[must_use]
    pub fn surface(mut self, provider: impl Surface + 'static) -> Self {
        self.surface = Some(Box::new(provider));
        self
    }

    /// The registry, or the first root trait left without a provider.
    pub fn build(self) -> Result<hd_run_wasmtime::native::Bindings, hd_run_wasmtime::native::Unregistered> {
        let mut bindings = hd_run_wasmtime::native::Bindings::new(CONTRACT);
        let Some(provider) = self.surface else {
            return Err(hd_run_wasmtime::native::Unregistered::new("local:00000000000000000000000000000000/main.Surface"));
        };
        bindings.register_dispatch("local:00000000000000000000000000000000/main.Surface", "hd:pkg:00000000000000000000000000000001", Box::new(provider), dispatch_Surface);
        Ok(bindings)
    }
}
